export const GUIDED: Record<string, GuidedLab> = {"labex-matplotlib-add-watermark-to-matplotlib-plot":{"intro":"In this lab, we will learn how to add a text watermark effect to a matplotlib plot.","steps":[{"title":"Import Necessary Libraries","body":["Before we start, we need to import the necessary libraries. In this lab, we will be using numpy and matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generate Data","body":["Let's generate some random data to plot."],"code":[{"lang":"python","text":"# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\nfig, ax = plt.subplots()\nax.plot(np.random.rand(20), '-o', ms=20, lw=2, alpha=0.7, mfc='orange')\nax.grid()"}]},{"title":"Add Text Watermark","body":["To add a text watermark, we can use the text() method of the Figure object. We need to provide the position, text, and other properties like font size, color, and transparency."],"code":[{"lang":"python","text":"ax.text(0.5, 0.5, 'created with matplotlib', transform=ax.transAxes,\n        fontsize=40, color='gray', alpha=0.5,\n        ha='center', va='center', rotation=30)"}]},{"title":"Display the Plot","body":["Finally, we can display the plot using the show() method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-web-application-server-sgskip":{"intro":"This tutorial lab will guide you through using Matplotlib in a Flask web application server. You will learn how to create figures using the .Figure constructor and save them to in-memory buffers, embed the resulting figures in HTML output, and run the Flask application using the flask command-line tool.","steps":[{"title":"Install Dependencies","body":["Before we get started, make sure you have the necessary packages installed. You can install them using pip."],"code":[{"lang":"python","text":"pip install matplotlib flask"}]},{"title":"Import Dependencies","body":["In this step, we will import the necessary dependencies. We will use base64 to encode the image data, BytesIO to store the image data in memory, Flask to create the web application server, and Figure to create the figures."],"code":[{"lang":"python","text":"import base64\nfrom io import BytesIO\n\nfrom flask import Flask\n\nfrom matplotlib.figure import Figure"}]},{"title":"Create the Flask Application","body":["In this step, we will create the Flask application. We will define a route for the home page (\"/\") and a function to generate and embed the Matplotlib figure."],"code":[{"lang":"python","text":"app = Flask(__name__)\n\n@app.route(\"/\")\ndef home():\n    # Generate the figure **without using pyplot**.\n    fig = Figure()\n    ax = fig.subplots()\n    ax.plot([1, 2])\n    # Save it to a temporary buffer.\n    buf = BytesIO()\n    fig.savefig(buf, format=\"png\")\n    # Embed the result in the html output.\n    data = base64.b64encode(buf.getbuffer()).decode(\"ascii\")\n    return f\"<img src='data:image/png;base64,{data}'/>\""}]},{"title":"Run the Flask Application","body":["In this step, we will run the Flask application using the flask command-line tool. Assuming that the working directory contains this script, run the following command to start the server:"],"code":[{"lang":"console","text":"FLASK_APP=matplot_lib_tutorial_lab flask run"}]},{"title":"View the Output","body":["In this step, we will view the output of the Flask application by navigating to http://localhost:5000/ in a web browser. The Matplotlib figure should be displayed on the page."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-3d-wireframe-visualizations-with-pyth":{"intro":"This lab will guide you through creating a 3D wireframe plot using Python's Matplotlib library. A wireframe plot is a visual representation of a 3D surface where lines are drawn between each point on the surface. This type of plot is useful for visualizing complex 3D data and can be customized to create impressive visualizations.","steps":[{"title":"Import Libraries","body":["The first step is to import the necessary libraries. In this lab, we will use the Matplotlib library to create the wireframe plot and NumPy library to generate the data."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom mpl_toolkits.mplot3d import axes3d\nimport numpy as np"}]},{"title":"Generate Data","body":["Next, we will generate the data that we will use to create the wireframe plot. In this lab, we will use the np.meshgrid() function to create the X, Y, and Z coordinates."],"code":[{"lang":"python","text":"# Generate data\nX, Y = np.meshgrid(np.arange(-5, 5, 0.25), np.arange(-5, 5, 0.25))\nR = np.sqrt(X**2 + Y**2)\nZ = np.sin(R)"}]},{"title":"Create the Plot","body":["Now that we have our data, we can create the wireframe plot. In this example, we will use the plot_wireframe() function to create the plot."],"code":[{"lang":"python","text":"# Create the plot\nfig = plt.figure()\nax = fig.add_subplot(111, projection='3d')\nax.plot_wireframe(X, Y, Z, rstride=5, cstride=5)"}]},{"title":"Customize the Plot","body":["We can customize the plot to make it more visually appealing. In this example, we will add a title, axis labels, and change the color of the plot."],"code":[{"lang":"python","text":"# Customize the plot\nax.set_title('Wireframe Plot')\nax.set_xlabel('X Label')\nax.set_ylabel('Y Label')\nax.set_zlabel('Z Label')\nax.plot_wireframe(X, Y, Z, rstride=5, cstride=5, color='green')"}]},{"title":"Display the Plot","body":["Finally, we can display the plot using the show() function."],"code":[{"lang":"python","text":"# Display the plot\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Display the plot\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-animate-a-3d-wireframe-plot":{"intro":"In this lab, we will learn how to animate a 3D wireframe plot using Matplotlib, a popular data visualization library in Python.","steps":[{"title":"Import Libraries","body":["The first step is to import the necessary libraries: Matplotlib, NumPy, and time."],"code":[{"lang":"python","text":"import time\nimport matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Set up the Figure and Subplot","body":["The second step is to set up the figure and subplot. We will create a 3D plot using add_subplot."],"code":[{"lang":"python","text":"fig = plt.figure()\nax = fig.add_subplot(projection='3d')"}]},{"title":"Create a Meshgrid","body":["The third step is to create a meshgrid using linspace."],"code":[{"lang":"python","text":"xs = np.linspace(-1, 1, 50)\nys = np.linspace(-1, 1, 50)\nX, Y = np.meshgrid(xs, ys)"}]},{"title":"Set Z Axis Limits","body":["The fourth step is to set the z axis limits so they aren't recalculated each frame."],"code":[{"lang":"python","text":"ax.set_zlim(-1, 1)"}]},{"title":"Animate the Plot","body":["The fifth step is to animate the plot. We will use a for loop to iterate through a range of values for phi. In each iteration, we will remove the previous line collection, generate new data, plot the new wireframe, and pause briefly before continuing."],"code":[{"lang":"python","text":"wframe = None\ntstart = time.time()\nfor phi in np.linspace(0, 180. / np.pi, 100):\n    if wframe:\n        wframe.remove()\n    Z = np.cos(2 * np.pi * X + phi) * (1 - np.hypot(X, Y))\n    wframe = ax.plot_wireframe(X, Y, Z, rstride=2, cstride=2)\n    plt.pause(.001)"}]},{"title":"Display the Average FPS","body":["The sixth step is to display the average frames per second (FPS) using the total time it took to run the animation."],"code":[{"lang":"python","text":"print('Average FPS: %f' % (100 / (time.time() - tstart)))"}]}],"commands":[],"reference":[{"path":"reference.py","text":"print('Average FPS: %f' % (100 / (time.time() - tstart)))"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-3d-wireframe-plotting":{"intro":"This lab is designed to show you how to create a 3D wireframe plot in Python using Matplotlib. A wireframe plot is a visual representation of a three-dimensional surface that displays the structure of the surface using lines. In this lab, we will show how to set the rstride and cstride parameters to control the density of the lines in the plot.","steps":[{"title":"Import necessary libraries","body":["We will start by importing the necessary libraries. In this case, we will use Matplotlib and the axes3d module."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom mpl_toolkits.mplot3d import axes3d"}]},{"title":"Create a figure and two subplots","body":["Create a figure and two subplots","We will create a figure with two subplots using subplots() method. We will also set the projection to '3d' so that our subplots will be three-dimensional."],"code":[{"lang":"python","text":"fig, (ax1, ax2) = plt.subplots(\n    2, 1, figsize=(8, 12), subplot_kw={'projection': '3d'})"}]},{"title":"Get the test data","body":["We will use the get_test_data() method from axes3d module to get the test data."],"code":[{"lang":"python","text":"X, Y, Z = axes3d.get_test_data(0.05)"}]},{"title":"Create the first subplot","body":["We will create the first subplot with the rstride parameter set to 10 and cstride parameter set to 0."],"code":[{"lang":"python","text":"ax1.plot_wireframe(X, Y, Z, rstride=10, cstride=0)\nax1.set_title(\"Column (x) stride set to 0\")"}]},{"title":"Create the second subplot","body":["We will create the second subplot with the rstride parameter set to 0 and cstride parameter set to 10."],"code":[{"lang":"python","text":"ax2.plot_wireframe(X, Y, Z, rstride=0, cstride=10)\nax2.set_title(\"Row (y) stride set to 0\")"}]},{"title":"Show the plot","body":["We will show the plot using the show() method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-adding-a-cursor-in-wx":{"intro":"This tutorial will guide you through the process of adding a cursor in WX to report data coordinates. We will be using Matplotlib, a plotting library for Python that provides tools to create a variety of plots, charts, and graphs.","steps":[{"title":"Create a Canvas Frame","body":["First, we will create a canvas frame that will hold the Matplotlib plot. We will add a sinusoidal plot to demonstrate the cursor functionality."],"code":[{"lang":"python","text":"class CanvasFrame(wx.Frame):\n    def __init__(self, ):\n        super().__init__(None, -1, 'CanvasFrame', size=(550, 350))\n\n        # Create a Figure and add a subplot\n        self.figure = Figure()\n        self.axes = self.figure.add_subplot()\n        t = np.arange(0.0, 3.0, 0.01)\n        s = np.sin(2*np.pi*t)\n\n        # Plot the sinusoidal curve\n        self.axes.plot(t, s)\n        self.axes.set_xlabel('t')\n        self.axes.set_ylabel('sin(t)')\n\n        # Create a FigureCanvas to display the plot\n        self.figure_canvas = FigureCanvas(self, -1, self.figure)\n\n        # Bind the motion_notify_event to update the status bar\n        self.figure_canvas.mpl_connect(\n            'motion_notify_event', self.UpdateStatusBar)\n\n        # Bind the enter_window event to change the cursor\n        self.figure_canvas.Bind(wx.EVT_ENTER_WINDOW, self.ChangeCursor)\n\n        # Create a sizer and add the FigureCanvas to it\n        self.sizer = wx.BoxSizer(wx.VERTICAL)\n        self.sizer.Add(self.figure_canvas, 1, wx.LEFT | wx.TOP | wx.GROW)\n        self.SetSizer(self.sizer)\n        self.Fit()\n\n        # Create a status bar to report the cursor location\n        self.statusBar = wx.StatusBar(self, -1)\n        self.SetStatusBar(self.statusBar)\n\n        # Create a toolbar to navigate the plot\n        self.toolbar = NavigationToolbar2Wx(self.figure_canvas)\n        self.sizer.Add(self.toolbar, 0, wx.LEFT | wx.EXPAND)\n        self.toolbar.Show()"}]},{"title":"Change the Cursor","body":["Next, we will define a method to change the cursor when it enters the canvas frame. In this case, we will change the cursor to a bullseye."],"code":[{"lang":"python","text":"def ChangeCursor(self, event):\n    self.figure_canvas.SetCursor(wx.Cursor(wx.CURSOR_BULLSEYE))"}]},{"title":"Update the Status Bar","body":["Finally, we will define a method to update the status bar with the cursor location whenever the mouse moves over the plot."],"code":[{"lang":"python","text":"def UpdateStatusBar(self, event):\n    if event.inaxes:\n        self.statusBar.SetStatusText(f\"x={event.xdata}  y={event.ydata}\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"def UpdateStatusBar(self, event):\n    if event.inaxes:\n        self.statusBar.SetStatusText(f\"x={event.xdata}  y={event.ydata}\")"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-xcorr-acorr-demo":{"intro":"The purpose of this lab is to demonstrate the use of cross-correlation and auto-correlation plots using the Python Matplotlib library. Cross-correlation and auto-correlation are mathematical tools used to measure the similarity between two signals. Cross-correlation measures the similarity between two different signals, while auto-correlation measures the similarity between a signal and a time-delayed version of itself. These tools are commonly used in signal processing, image analysis, and time series analysis.","steps":[{"title":"Import Libraries","body":["First, we need to import the necessary libraries. In this lab, we will be using NumPy and Matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generate Random Data","body":["Next, we will generate two arrays of random data using NumPy. We will use these arrays to demonstrate cross-correlation and auto-correlation."],"code":[{"lang":"python","text":"np.random.seed(19680801)\nx, y = np.random.randn(2, 100)"}]},{"title":"Plot Cross-Correlation","body":["We will now plot the cross-correlation between the two arrays using the xcorr function in Matplotlib.","The xcorr function takes the following parameters:","• x: the first array of data • y: the second array of data • usevlines: boolean, whether to plot vertical lines from 0 to the correlation value • maxlags: integer, the maximum number of lags to calculate the correlation for • normed: boolean, whether to normalize the correlation values • lw: integer, the line width for the plot"],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.xcorr(x, y, usevlines=True, maxlags=50, normed=True, lw=2)\nax.grid(True)\nplt.show()"}]},{"title":"Plot Auto-Correlation","body":["We will now plot the auto-correlation of the x array using the acorr function in Matplotlib.","The acorr function takes the following parameters:","• x: the array of data to calculate the auto-correlation for • usevlines: boolean, whether to plot vertical lines from 0 to the correlation value • normed: boolean, whether to normalize the correlation values • maxlags: integer, the maximum number of lags to calculate the correlation for • lw: integer, the line width for the plot"],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.acorr(x, usevlines=True, normed=True, maxlags=50, lw=2)\nax.grid(True)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\nax.acorr(x, usevlines=True, normed=True, maxlags=50, lw=2)\nax.grid(True)\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-visualization-with-xkcd-style":{"intro":"Matplotlib is a data visualization library that provides various tools to create 2D and 3D plots. It is built on top of the NumPy library and its main purpose is to visualize data in a simple and effective way. In this tutorial, we will learn how to create two different types of plots using the xkcd style from the XKCD webcomic.","steps":[{"title":"Importing Libraries","body":["The first step is to import the necessary libraries. We will be using the matplotlib.pyplot and numpy libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Creating an XKCD-style Plot","body":["In this step, we will create an xkcd-style plot that shows the relationship between time and overall health. The plot is based on the \"Stove Ownership\" comic from XKCD."],"code":[{"lang":"python","text":"with plt.xkcd():\n    fig = plt.figure()\n    ax = fig.add_axes((0.1, 0.2, 0.8, 0.7))\n    ax.spines[['top', 'right']].set_visible(False)\n    ax.set_xticks([])\n    ax.set_yticks([])\n    ax.set_ylim([-30, 10])\n\n    data = np.ones(100)\n    data[70:] -= np.arange(30)\n\n    ax.annotate(\n        'THE DAY I REALIZED\\nI COULD COOK BACON\\nWHENEVER I WANTED',\n        xy=(70, 1), arrowprops=dict(arrowstyle='->'), xytext=(15, -10))\n\n    ax.plot(data)\n\n    ax.set_xlabel('time')\n    ax.set_ylabel('my overall health')\n    fig.text(\n        0.5, 0.05,\n        '\"Stove Ownership\" from xkcd by Randall Munroe',\n        ha='center')\n\nplt.show()"}]},{"title":"Creating a Bar Chart with XKCD Style","body":["Creating a Bar Chart with XKCD Style","In this step, we will create a bar chart with the XKCD style. The chart is based on the \"The Data So Far\" comic from XKCD."],"code":[{"lang":"python","text":"with plt.xkcd():\n    fig = plt.figure()\n    ax = fig.add_axes((0.1, 0.2, 0.8, 0.7))\n    ax.bar([0, 1], [0, 100], 0.25)\n    ax.spines[['top', 'right']].set_visible(False)\n    ax.xaxis.set_ticks_position('bottom')\n    ax.set_xticks([0, 1])\n    ax.set_xticklabels(['CONFIRMED BY\\nEXPERIMENT', 'REFUTED BY\\nEXPERIMENT'])\n    ax.set_xlim([-0.5, 1.5])\n    ax.set_yticks([])\n    ax.set_ylim([0, 110])\n\n    ax.set_title(\"CLAIMS OF SUPERNATURAL POWERS\")\n\n    fig.text(\n        0.5, 0.05,\n        '\"The Data So Far\" from xkcd by Randall Munroe',\n        ha='center')\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"with plt.xkcd():\n    fig = plt.figure()\n    ax = fig.add_axes((0.1, 0.2, 0.8, 0.7))\n    ax.bar([0, 1], [0, 100], 0.25)\n    ax.spines[['top', 'right']].set_visible(False)\n    ax.xaxis.set_ticks_position('bottom')\n    ax.set_xticks([0, 1])\n    ax.set_xticklabels(['CONFIRMED BY\\nEXPERIMENT', 'REFUTED BY\\nEXPERIMENT'])\n    ax.set_xlim([-0.5, 1.5])\n    ax.set_yticks([])\n    ax.set_ylim([0, 110])\n\n    ax.set_title(\"CLAIMS OF SUPERNATURAL POWERS\")\n\n    fig.text(\n        0.5, 0.05,\n        '\"The Data So Far\" from xkcd by Randall Munroe',\n        ha='center')\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-zoom-inset-axes":{"intro":"Matplotlib is a Python library used for creating static, animated, and interactive visualizations in Python. It is a powerful tool for data visualization, and it is widely used in the scientific community. In this lab, we will learn how to create a zoomed-in region in a Matplotlib plot.","steps":[{"title":"Import necessary libraries","body":["The first step is to import the necessary libraries. We will be using NumPy and Matplotlib for this example."],"code":[{"lang":"python","text":"import numpy as np\nfrom matplotlib import cbook\nfrom matplotlib import pyplot as plt"}]},{"title":"Create the plot","body":["Next, we will create a plot using some sample data. We will be using a bivariate normal distribution as our data source."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\n\n# make data\nZ = cbook.get_sample_data(\"axes_grid/bivariate_normal.npy\")  # 15x15 array\nZ2 = np.zeros((150, 150))\nny, nx = Z.shape\nZ2[30:30+ny, 30:30+nx] = Z\nextent = (-3, 4, -4, 3)\n\nax.imshow(Z2, extent=extent, origin=\"lower\")"}]},{"title":"Add an inset plot","body":["In this step, we will add an inset plot to the main plot. This inset plot will show a zoomed-in region of the main plot."],"code":[{"lang":"python","text":"# inset axes....\nx1, x2, y1, y2 = -1.5, -0.9, -2.5, -1.9  # subregion of the original image\naxins = ax.inset_axes(\n    [0.5, 0.5, 0.47, 0.47],\n    xlim=(x1, x2), ylim=(y1, y2), xticklabels=[], yticklabels=[])\naxins.imshow(Z2, extent=extent, origin=\"lower\")"}]},{"title":"Add a rectangle to show the zoomed-in region","body":["Add a rectangle to show the zoomed-in region","In this step, we will add a rectangle to the main plot to show where the zoomed-in region is located."],"code":[{"lang":"python","text":"ax.indicate_inset_zoom(axins, edgecolor=\"black\")"}]},{"title":"Display the plot","body":["Finally, we will display the plot using the plt.show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-event-handling-tutorial":{"intro":"This lab is a step-by-step tutorial on how to connect events in one window, for example, a mouse press, to another figure window in Python Matplotlib.","steps":[{"title":"Set up the environment","body":[],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\nfigsrc, axsrc = plt.subplots(figsize=(3.7, 3.7))\nfigzoom, axzoom = plt.subplots(figsize=(3.7, 3.7))\naxsrc.set(xlim=(0, 1), ylim=(0, 1), autoscale_on=False,\n          title='Click to zoom')\naxzoom.set(xlim=(0.45, 0.55), ylim=(0.4, 0.6), autoscale_on=False,\n           title='Zoom window')\n\nx, y, s, c = np.random.rand(4, 200)\ns *= 200\n\naxsrc.scatter(x, y, s, c)\naxzoom.scatter(x, y, s, c)"}]},{"title":"Define the on_press function","body":[],"code":[{"lang":"python","text":"def on_press(event):\n    if event.button != 1:\n        return\n    x, y = event.xdata, event.ydata\n    axzoom.set_xlim(x - 0.1, x + 0.1)\n    axzoom.set_ylim(y - 0.1, y + 0.1)\n    figzoom.canvas.draw()"}]},{"title":"Connect the event to the function","body":["Connect the event to the function","Now, we connect the button press event in the first window to the on_press function we just defined."],"code":[{"lang":"python","text":"figsrc.canvas.mpl_connect('button_press_event', on_press)"}]},{"title":"Display the plot","body":["Finally, we display the plot to the user."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-adjusting-matplotlib-drawing-order":{"intro":"In this tutorial, we will learn about the drawing order of artists in Matplotlib and how to adjust the order using the zorder attribute. We will also explore how to change the order for individual artists and the default value of zorder for different types of artists.","steps":[{"title":"Understanding Zorder","body":["The zorder attribute in Matplotlib is a floating point number that determines the drawing order of artists. Artists with higher zorder are drawn on top of those with lower zorder. The default value of zorder depends on the type of the artist. For example, images have a default zorder of 0, while patches have a default zorder of 1."],"code":[]},{"title":"Changing Zorder","body":["To change the drawing order of artists, we can set their zorder attribute explicitly using the zorder parameter when creating the artist. For example, we can move dots on top of lines in a scatter plot by setting the zorder of the dots to a value higher than the zorder of the line."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nr = np.linspace(0.3, 1, 30)\ntheta = np.linspace(0, 4*np.pi, 30)\nx = r * np.sin(theta)\ny = r * np.cos(theta)\n\nfig, (ax1, ax2) = plt.subplots(1, 2, figsize=(6, 3.2))\n\nax1.plot(x, y, 'C3', lw=3)\nax1.scatter(x, y, s=120)\nax1.set_title('Lines on top of dots')\n\nax2.plot(x, y, 'C3', lw=3)\nax2.scatter(x, y, s=120, zorder=2.5)  # move dots on top of line\nax2.set_title('Dots on top of lines')\n\nplt.tight_layout()\nplt.show()"}]},{"title":"Setting Zorder for Ticks and Grid Lines","body":["Setting Zorder for Ticks and Grid Lines","We can use the set_axisbelow() method or the axes.axisbelow parameter to set the zorder of ticks and grid lines."],"code":[{"lang":"python","text":"ax = plt.axes()\nax.plot([1, 2, 3], [2, 4, 3])\nax.set_axisbelow(True)\nax.yaxis.grid(color='gray', linestyle='dashed')"}]},{"title":"Custom Order of Elements","body":["We can also set the zorder of elements in a custom order. For example, we can set the zorder of a legend to be between two lines."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nx = np.linspace(0, 7.5, 100)\nplt.rcParams['lines.linewidth'] = 5\nplt.figure()\nplt.plot(x, np.sin(x), label='zorder=2', zorder=2)  # bottom\nplt.plot(x, np.sin(x+0.5), label='zorder=3',  zorder=3)\nplt.axhline(0, label='zorder=2.5', color='lightgrey', zorder=2.5)\nplt.title('Custom order of elements')\nl = plt.legend(loc='upper right')\nl.set_zorder(2.5)  # legend between blue and orange line\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nx = np.linspace(0, 7.5, 100)\nplt.rcParams['lines.linewidth'] = 5\nplt.figure()\nplt.plot(x, np.sin(x), label='zorder=2', zorder=2)  # bottom\nplt.plot(x, np.sin(x+0.5), label='zorder=3',  zorder=3)\nplt.axhline(0, label='zorder=2.5', color='lightgrey', zorder=2.5)\nplt.title('Custom order of elements')\nl = plt.legend(loc='upper right')\nl.set_zorder(2.5)  # legend between blue and orange line\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-a-line-plot-with-matplotlib":{"intro":"In this lab, we will learn how to create a line plot using Matplotlib. Line plots are a basic visualization that can be used to represent data points connected by straight line segments. We will use the Matplotlib library in Python to create a line plot.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","First, we need to import the Matplotlib library, as well as any other libraries that we will be using. In this example, we will also import the NumPy library to generate some sample data for our line plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generate sample data","body":["Next, we will generate some sample data to plot. In this example, we will create two arrays, x and y, where x represents the x-coordinates of the data points and y represents the y-coordinates."],"code":[{"lang":"python","text":"x = np.linspace(0, 10, 100)\ny = np.sin(x)"}]},{"title":"Create the line plot","body":["Now that we have our sample data, we can create the line plot using the plot function from the Matplotlib library. We will pass in the x and y arrays as arguments to the plot function."],"code":[{"lang":"python","text":"plt.plot(x, y)"}]},{"title":"Customize the plot","body":["We can customize the plot by adding labels to the x and y axes, a title to the plot, and a legend. We can also change the line style and color."],"code":[{"lang":"python","text":"plt.plot(x, y, linestyle='--', color='red', label='sin(x)')\nplt.xlabel('x')\nplt.ylabel('y')\nplt.title('Line Plot')\nplt.legend()"}]},{"title":"Display the plot","body":[],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-pyplot-interface-tutorial":{"intro":"This tutorial provides a step-by-step guide to using the pyplot interface in Matplotlib. The pyplot module is a collection of functions that make Matplotlib work like MATLAB, allowing you to easily create and customize plots. This tutorial assumes you have a basic understanding of Matplotlib and its concepts.","steps":[{"title":"Generating a Simple Plot","body":["To start, let's generate a simple plot using the plot function in pyplot. In this example, we'll plot a line graph with the y-values [1, 2, 3, 4]:","• We import the pyplot module from matplotlib and alias it as plt. • The plot function is used to generate a line graph. By providing a single list of y-values, the x-values are automatically generated as [0, 1, 2, 3], since Python ranges start with 0. • The ylabel function sets the label for the y-axis. • Finally, the show function displays the plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nplt.plot([1, 2, 3, 4])\nplt.ylabel('some numbers')\nplt.show()"}]},{"title":"Formatting the Style of the Plot","body":["Formatting the Style of the Plot","Next, let's customize the style of our plot. We can use the optional third argument of the plot function to specify the format string, which indicates the color and line type of the plot. For example, let's plot the same line graph with red circles:","• We use the format string 'ro' to indicate red circles for the plot. • The axis function is used to set the viewport of the axes, specifying the range of values for the x- and y-axis."],"code":[{"lang":"python","text":"plt.plot([1, 2, 3, 4], [1, 4, 9, 16], 'ro')\nplt.axis([0, 6, 0, 20])\nplt.show()"}]},{"title":"Plotting Multiple Lines","body":["We can also plot multiple lines with different styles in one function call using arrays. Let's plot three lines: a dashed red line, blue squares, and green triangles:","• We use the numpy module to create an array t with evenly sampled time values. • The plot function is called with three pairs of x and y values, followed by the format strings 'r--' (dashed red line), 'bs' (blue squares), and 'g^' (green triangles)."],"code":[{"lang":"python","text":"import numpy as np\n\nt = np.arange(0., 5., 0.2)\n\nplt.plot(t, t, 'r--', t, t**2, 'bs', t, t**3, 'g^')\nplt.show()"}]},{"title":"Plotting with Categorical Variables","body":["Plotting with Categorical Variables","Matplotlib allows you to create plots using categorical variables. Let's create a bar plot, scatter plot, and line plot with categorical variables:","• We create a list names with three categorical values and a list values representing their corresponding values. • The figure function is called to create a new figure with a specified size. • We use the subplot function to create a grid of subplots. In this example, we create three subplots, each with a different type of plot: bar plot, scatter plot, and line plot. • The suptitle function is used to set the super-title of the figure."],"code":[{"lang":"python","text":"names = ['group_a', 'group_b', 'group_c']\nvalues = [1, 10, 100]\n\nplt.figure(figsize=(9, 3))\n\nplt.subplot(131)\nplt.bar(names, values)\nplt.subplot(132)\nplt.scatter(names, values)\nplt.subplot(133)\nplt.plot(names, values)\n\nplt.suptitle('Categorical Plotting')\nplt.show()"}]},{"title":"Customizing Line Properties","body":["Matplotlib allows you to customize various line properties, such as linewidth, dash style, and color. Let's demonstrate some ways to set line properties:","• We create an array x and compute the corresponding y-values using the np.sin function. • The plot function is called to create a line plot. • We use the set method of the Line2D instance to set the linewidth property of the line to 2.0. • Alternatively, we can use the setp function to set multiple properties of the line, such as color and linewidth, using keyword arguments."],"code":[{"lang":"python","text":"x = np.arange(0, 5, 0.1)\nline, = plt.plot(x, np.sin(x), '-')\n\n# Using the Line2D instance's setter method\nline.set_linewidth(2.0)  # Set the linewidth property of the line to 2.0\n\n# Using the pyplot.setp function\nplt.setp(line, color='r', linewidth=2.0)  # Set the color and linewidth properties using the setp function\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"x = np.arange(0, 5, 0.1)\nline, = plt.plot(x, np.sin(x), '-')\n\n# Using the Line2D instance's setter method\nline.set_linewidth(2.0)  # Set the linewidth property of the line to 2.0\n\n# Using the pyplot.setp function\nplt.setp(line, color='r', linewidth=2.0)  # Set the color and linewidth properties using the setp function\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-image-plotting-with-matplotlib":{"intro":"In this lab, you will learn how to plot and manipulate images using the Matplotlib library in Python. You will learn how to import image data into NumPy arrays, plot numpy arrays as images, apply pseudocolor schemes, add color scale references, examine specific data ranges, and explore different interpolation schemes.","steps":[{"title":"Importing Image Data","body":["To begin, we need to import the necessary libraries and load the image data into a NumPy array. In our case, we will use the PIL library to load the image, and then convert it into a NumPy array."],"code":[{"lang":"python","text":"from PIL import Image\nimport matplotlib.pyplot as plt\nimport numpy as np\n\nimg = np.asarray(Image.open('./stinkbug.png'))"}]},{"title":"Plotting Images","body":["Now that we have the image data in a NumPy array, we can plot it using the imshow function from matplotlib.pyplot. This function takes the image array as input and displays it as an image plot."],"code":[{"lang":"python","text":"plt.imshow(img)"}]},{"title":"Applying Pseudocolor Schemes","body":["Pseudocolor schemes can be used to enhance contrast and visualize data more easily. If the image is grayscale, we can apply pseudocolor schemes by specifying different colormaps. We can do this by using the cmap parameter in the imshow function."],"code":[{"lang":"python","text":"lum_img = img[:, :, 0]\nplt.imshow(lum_img, cmap=\"hot\")"}]},{"title":"Adding Color Scale Reference","body":["To provide a reference for the color scale, we can add a color bar to the plot. This can be done using the colorbar function from matplotlib.pyplot."],"code":[{"lang":"python","text":"imgplot = plt.imshow(lum_img)\nplt.colorbar()"}]},{"title":"Examining Specific Data Ranges","body":["Examining Specific Data Ranges","Sometimes, it might be necessary to examine specific data ranges in an image. We can do this by adjusting the colormap limits using the clim parameter in the imshow function. This allows us to focus on specific regions of the image while sacrificing detail in other regions."],"code":[{"lang":"python","text":"min_value, max_value = 100, 200\nplt.imshow(img, clim=(min_value, max_value))"}]},{"title":"Array Interpolation Schemes","body":["When resizing an image, it is necessary to interpolate the pixel values to fill the missing space. Different interpolation schemes can be used to determine the value of a pixel based on its surrounding pixels. Matplotlib provides different interpolation options, such as \"nearest\", \"bilinear\", and \"bicubic\"."],"code":[{"lang":"python","text":"plt.imshow(img, interpolation=\"bilinear\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.imshow(img, interpolation=\"bilinear\")"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-the-lifecycle-of-a-plot":{"intro":"In this lab, we will explore the lifecycle of a plot using Matplotlib. We will start with raw data and end by saving a customized visualization. We will learn how to create a plot, control its style, customize its appearance, combine multiple visualizations, and save the plot to disk.","steps":[{"title":"Import the necessary modules","body":["First, we need to import the required modules: Matplotlib and NumPy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Prepare the data","body":["We will use a sample dataset that contains sales information for different companies. Here is an example of the data:"],"code":[{"lang":"python","text":"data = {'Barton LLC': 109438.50,\n        'Frami, Hills and Schmidt': 103569.59,\n        'Fritsch, Russel and Anderson': 112214.71,\n        'Jerde-Hilpert': 112591.43,\n        'Keeling LLC': 100934.30,\n        'Koepp Ltd': 103660.54,\n        'Kulas Inc': 137351.96,\n        'Trantow-Barrows': 123381.38,\n        'White-Trantow': 135841.99,\n        'Will LLC': 104437.60}\ngroup_data = list(data.values())\ngroup_names = list(data.keys())\ngroup_mean = np.mean(group_data)"}]},{"title":"Create the plot","body":["We will use the barplot visualization to represent the sales data. Follow these steps:","• Create a figure and an axis object using plt.subplots().","• Plot the data using the barh() method of the axis object."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()"},{"lang":"python","text":"ax.barh(group_names, group_data)"}]},{"title":"Customize the plot style","body":["We can change the style of our plot to make it more visually appealing. Follow these steps:","• Print the list of available styles using print(plt.style.available).","• Choose a style and apply it using plt.style.use(style_name)."],"code":[{"lang":"python","text":"print(plt.style.available)"},{"lang":"python","text":"plt.style.use('fivethirtyeight')"},{"lang":"python","text":"fig, ax = plt.subplots()\nax.barh(group_names, group_data)"}]},{"title":"Customize the plot appearance","body":["We can further customize the appearance of our plot. Follow these steps:","• Rotate the x-axis labels to make them more readable.","• Set the x-axis and y-axis limits, labels, and title."],"code":[{"lang":"python","text":"labels = ax.get_xticklabels()\nplt.setp(labels, rotation=45, horizontalalignment='right')"},{"lang":"python","text":"ax.set(xlim=[-10000, 140000],\n       xlabel='Total Revenue',\n       ylabel='Company',\n       title='Company Revenue')"},{"lang":"python","text":"fig, ax = plt.subplots()\nax.barh(group_names, group_data)\nlabels = ax.get_xticklabels()\nplt.setp(labels, rotation=45, horizontalalignment='right')\nax.set(xlim=[-10000, 140000], xlabel='Total Revenue', ylabel='Company',\n       title='Company Revenue')"}]},{"title":"Combine multiple visualizations","body":["Combine multiple visualizations","We can add additional plot elements to our visualization. Follow these steps:","• Add a vertical line representing the mean of the sales data.","• Annotate new companies on the plot."],"code":[{"lang":"python","text":"ax.axvline(group_mean, ls='--', color='r')"},{"lang":"python","text":"for group in [3, 5, 8]:\n    ax.text(145000, group, \"New Company\", fontsize=10, verticalalignment=\"center\")"},{"lang":"python","text":"ax.title.set(y=1.05)"}]},{"title":"Save the plot","body":["Finally, we can save our plot to disk. Follow these steps:","• Print the supported file formats using print(fig.canvas.get_supported_filetypes()).","• Save the figure as an image file using fig.savefig(file_path, transparent=False, dpi=80, bbox_inches=\"tight\"). Uncomment this line to save the figure.","You can open the saved image file using the file explorer in the left sidebar."],"code":[{"lang":"python","text":"print(fig.canvas.get_supported_filetypes())"},{"lang":"python","text":"fig.savefig('sales.png', transparent=False, dpi=80, bbox_inches=\"tight\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig.savefig('sales.png', transparent=False, dpi=80, bbox_inches=\"tight\")"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-customizing-matplotlib-visualizations":{"intro":"This lab will guide you through the process of customizing Matplotlib using style sheets and rcParams. Matplotlib is a powerful library for creating visualizations in Python. By customizing the properties and default styles of Matplotlib, you can create unique and visually appealing plots.","steps":[{"title":"Setting rcParams at runtime","body":["You can dynamically change the default runtime configuration settings in a Python script or interactively from the Python shell. The matplotlib.rcParams variable is global to the Matplotlib package and stores all the rc settings. To customize rcParams at runtime, you can modify it directly using the mpl.rcParams dictionary. Here's an example:","This code changes the default line width and line style for all plots created with Matplotlib.","Let's see some random data plotted with the new default settings."],"code":[{"lang":"python","text":"import matplotlib as mpl\n\nmpl.rcParams['lines.linewidth'] = 2\nmpl.rcParams['lines.linestyle'] = '--'"},{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nimport matplotlib as mpl\nfrom cycler import cycler\nmpl.rcParams['lines.linewidth'] = 2\nmpl.rcParams['lines.linestyle'] = '--'\ndata = np.random.randn(50)\nplt.plot(data)\nplt.show()"}]},{"title":"Using style sheets","body":["Another way to change the visual appearance of plots is to set the rcParams in a style sheet and import that style sheet with matplotlib.style.use. A style sheet is a file that contains a set of rcParams related to the style of a plot. Matplotlib provides a number of pre-defined styles that you can use. For example, the \"ggplot\" style emulates the aesthetics of the ggplot library in R. You can apply a style sheet like this:","You can also define your own custom styles and use them by calling .style.use with the path or URL to the style sheet."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nprint(plt.style.available)\nplt.style.use('Solarize_Light2')"}]},{"title":"Changing the matplotlibrc file","body":["Changing the matplotlibrc file","The matplotlibrc file is a configuration file that allows you to customize all kinds of properties in Matplotlib. It controls the defaults for properties like figure size, line width, colors, fonts, etc. You can modify the matplotlibrc file to customize Matplotlib according to your preferences. The file can be located in different places on your system, and Matplotlib looks for it in a specific order. Once a matplotlibrc file is found, it takes precedence over other settings. You can use the matplotlib.matplotlib_fname() function to display the path of the currently active matplotlibrc file."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"}};
